module popcount16 (
    input  logic [15:0] x,
    output logic [4:0]  count
);

    logic [1:0] p [8];  // pair sums (0..2)
    logic [2:0] q [4];  // quad sums (0..4)
    logic [3:0] r [2];  // octet sums (0..8)

    genvar i;
    generate
        for (i = 0; i < 8; i++) begin : g_pair
            assign p[i] = {1'b0, x[2*i]} + {1'b0, x[2*i+1]};
        end
        for (i = 0; i < 4; i++) begin : g_quad
            assign q[i] = {1'b0, p[2*i]} + {1'b0, p[2*i+1]};
        end
        for (i = 0; i < 2; i++) begin : g_oct
            assign r[i] = {1'b0, q[2*i]} + {1'b0, q[2*i+1]};
        end
    endgenerate

    assign count = {1'b0, r[0]} + {1'b0, r[1]};

endmodule

