module alu8 (
    input  logic [7:0] a,
    input  logic [7:0] b,
    input  logic [2:0] op,
    output logic [7:0] y,
    output logic       zero,
    output logic       carry
);

    logic [8:0] add_res;
    logic [8:0] sub_res;
    logic       slt_bit;

    always_comb begin
        add_res = {1'b0, a} + {1'b0, b};
        sub_res = {1'b0, a} - {1'b0, b};
        // Signed less-than: if signs differ, a is less when a is negative;
        // otherwise unsigned comparison gives the correct order.
        if (a[7] != b[7])
            slt_bit = a[7];
        else
            slt_bit = (a < b);
    end

    always_comb begin
        y     = 8'd0;
        carry = 1'b0;
        case (op)
            3'b000: begin
                y     = add_res[7:0];
                carry = add_res[8];
            end
            3'b001: begin
                y     = sub_res[7:0];
                carry = (a < b);
            end
            3'b010: y = a & b;
            3'b011: y = a | b;
            3'b100: y = a ^ b;
            3'b101: y = {7'd0, slt_bit};
            3'b110: y = a << b[2:0];
            3'b111: y = a >> b[2:0];
            default: y = 8'd0;
        endcase
    end

    assign zero = (y == 8'd0);

endmodule

module alu8 (
    input  logic [7:0] a,
    input  logic [7:0] b,
    input  logic [2:0] op,
    output logic [7:0] y,
    output logic       zero,
    output logic       carry
);

    logic [8:0] add_res;
    logic [8:0] sub_res;
    logic       lt_u;
    logic       lt_s;

    always_comb begin
        add_res = {1'b0, a} + {1'b0, b};
        sub_res = {1'b0, a} - {1'b0, b};
        lt_u    = (a < b);
        // Signed less-than: if signs differ, a is less when a is negative;
        // if signs match, unsigned ordering matches signed ordering.
        lt_s    = (a[7] & ~b[7]) | (~(a[7] ^ b[7]) & lt_u);
    end

    always_comb begin
        y     = 8'd0;
        carry = 1'b0;
        case (op)
            3'b000: begin
                y     = add_res[7:0];
                carry = add_res[8];
            end
            3'b001: begin
                y     = sub_res[7:0];
                carry = sub_res[8];
            end
            3'b010: y = a & b;
            3'b011: y = a | b;
            3'b100: y = a ^ b;
            3'b101: y = {7'd0, lt_s};
            3'b110: y = a << b[2:0];
            3'b111: y = a >> b[2:0];
            default: y = 8'd0;
        endcase
    end

    assign zero = (y == 8'd0);

endmodule

