            3'b011: y = a | b;
            3'b100: y = a ^ b;
            3'b101: y = ($signed(a) < $signed(b)) ? 8'd1 : 8'd0;
            3'b110: y = a << b[2:0];
            3'b111: y = a >> b[2:0];
            default: begin
                y     = 8'd0;
                carry = 1'b0;
            end
        endcase
    end

