module alu8 (
    input  logic [7:0] a,
    input  logic [7:0] b,
    input  logic [2:0] op,
    output logic [7:0] y,
    output logic       zero,
    output logic       carry
);

    logic [8:0] add_res;
    logic [8:0] sub_res;
    logic       lt_unsigned;
    logic       lt_signed;

    assign add_res     = {1'b0, a} + {1'b0, b};
    assign sub_res     = {1'b0, a} - {1'b0, b};
    assign lt_unsigned = sub_res[8];
    // Signed less-than: if signs differ, the negative operand is smaller;
    // otherwise the unsigned comparison gives the correct ordering.
    assign lt_signed   = (a[7] ^ b[7]) ? a[7] : lt_unsigned;

    always_comb begin
        y     = 8'd0;
        carry = 1'b0;
        unique case (op)
            3'b000: begin
                y     = add_res[7:0];
                carry = add_res[8];
            end
            3'b001: begin
                y     = sub_res[7:0];
                carry = lt_unsigned;
            end
            3'b010: y = a & b;
            3'b011: y = a | b;
            3'b100: y = a ^ b;
            3'b101: y = {7'd0, lt_signed};
            3'b110: y = a << b[2:0];
            3'b111: y = a >> b[2:0];
            default: y = 8'd0;
        endcase
    end

    assign zero = (y == 8'd0);

endmodule

module up_down_counter (
    input  logic       clk,
    input  logic       rst,   // synchronous, active high
    input  logic       en,
    input  logic       up,    // 1 = count up, 0 = count down
    input  logic       load,
    input  logic [7:0] d,
    output logic [7:0] q
);

    always_ff @(posedge clk) begin
        if (rst)
            q <= 8'd0;
        else if (load)
            q <= d;
        else if (en)
            q <= up ? q + 8'd1 : q - 8'd1;
    end

endmodule

