module seq_detect_1011 (
    input  logic clk,
    input  logic rst,    // synchronous, active high
    input  logic din,    // serial input, one bit per clock
    output logic match
);

    // hist[2] = oldest of the last three bits, hist[0] = newest
    logic [2:0] hist;

    always_ff @(posedge clk) begin
        if (rst) begin
            hist  <= 3'b000;
            match <= 1'b0;
        end else begin
            match <= (hist == 3'b101) && din;
            hist  <= {hist[1:0], din};
        end
    end

endmodule

module seq_detect_1011 (
    input  logic clk,
    input  logic rst,    // synchronous, active high
    input  logic din,    // serial input, one bit per clock
    output logic match
);

    // hist[2] = oldest of the last three sampled bits, hist[0] = most recent
    logic [2:0] hist;

    always_ff @(posedge clk) begin
        if (rst) begin
            hist  <= 3'b000;
            match <= 1'b0;
        end else begin
            hist  <= {hist[1:0], din};
            // Window (arrival order): hist[2], hist[1], hist[0], din = 1,0,1,1
            match <= hist[2] & ~hist[1] & hist[0] & din;
        end
    end

endmodule

