module fifo_sync #(
    parameter int W     = 8,   // data width
    parameter int DEPTH = 8    // number of entries, a power of 2
) (
    input  logic                   clk,
    input  logic                   rst,     // synchronous, active high
    input  logic                   wr_en,
    input  logic [W-1:0]           din,
    input  logic                   rd_en,
    output logic [W-1:0]           dout,
    output logic                   full,
    output logic                   empty,
    output logic [$clog2(DEPTH):0] count
);

    localparam int AW = $clog2(DEPTH);

    logic [W-1:0]  mem [DEPTH];
    logic [AW-1:0] wp;
    logic [AW-1:0] rp;
    logic [AW:0]   cnt;

    logic do_wr;
    logic do_rd;

    assign full  = (cnt == DEPTH[AW:0]);
    assign empty = (cnt == '0);
    assign count = cnt;

    assign do_wr = wr_en & ~full;
    assign do_rd = rd_en & ~empty;

    // Storage and pointers
    always_ff @(posedge clk) begin
        if (rst) begin
            wp  <= '0;
            rp  <= '0;
            cnt <= '0;
        end else begin
            if (do_wr) begin
                mem[wp] <= din;
                wp      <= wp + 1'b1;
            end
            if (do_rd) begin
                rp <= rp + 1'b1;
            end
            if (do_wr & ~do_rd) begin
                cnt <= cnt + 1'b1;
            end else if (do_rd & ~do_wr) begin
                cnt <= cnt - 1'b1;
            end
        end
    end

    // Registered output data
    always_ff @(posedge clk) begin
        if (rst) begin
            dout <= '0;
        end else if (do_rd) begin
            dout <= mem[rp];
        end
    end

endmodule

module fifo_sync #(
    parameter int W     = 8,   // data width
    parameter int DEPTH = 8    // number of entries, a power of 2
) (
    input  logic                   clk,
    input  logic                   rst,     // synchronous, active high
    input  logic                   wr_en,
    input  logic [W-1:0]           din,
    input  logic                   rd_en,
    output logic [W-1:0]           dout,
    output logic                   full,
    output logic                   empty,
    output logic [$clog2(DEPTH):0] count
);

    localparam int AW = $clog2(DEPTH);

    logic [W-1:0]  mem [DEPTH];
    logic [AW-1:0] wptr;
    logic [AW-1:0] rptr;
    logic [AW:0]   cnt;

    logic do_wr;
    logic do_rd;

    assign full  = (cnt == DEPTH[AW:0]);
    assign empty = (cnt == '0);
    assign count = cnt;

    assign do_wr = wr_en && !full;
    assign do_rd = rd_en && !empty;

    always_ff @(posedge clk) begin
        if (rst) begin
            cnt  <= '0;
            wptr <= '0;
            rptr <= '0;
            dout <= '0;
        end else begin
            if (do_wr) begin
                mem[wptr] <= din;
                wptr      <= wptr + 1'b1;
            end

            if (do_rd) begin
                dout <= mem[rptr];
                rptr <= rptr + 1'b1;
            end

            if (do_wr && !do_rd)
                cnt <= cnt + 1'b1;
            else if (do_rd && !do_wr)
                cnt <= cnt - 1'b1;
        end
    end

endmodule

