    output logic [$clog2(DEPTH):0] count
);

    localparam int AW = $clog2(DEPTH);

    logic [W-1:0]  mem [DEPTH];
    logic [AW-1:0] wptr;
    logic [AW-1:0] rptr;

    assign full  = (count == DEPTH[AW:0]);
    assign empty = (count == '0);

    wire do_wr = wr_en && !full;
    wire do_rd = rd_en && !empty;

    always_ff @(posedge clk) begin
        if (rst) begin
            wptr  <= '0;
            rptr  <= '0;
            count <= '0;
            dout  <= '0;
        end else begin
            if (do_wr) begin
                mem[wptr] <= din;
                wptr      <= wptr + 1'b1;
            end
            if (do_rd) begin
                dout  <= mem[rptr];
                rptr  <= rptr + 1'b1;
            end
            case ({do_wr, do_rd})
                2'b10:   count <= count + 1'b1;
                2'b01:   count <= count - 1'b1;
                default: count <= count;
            endcase
        end
    end

endmodule

module fifo_sync #(
    parameter int W     = 8,   // data width
    parameter int DEPTH = 8    // number of entries, a power of 2
) (
    input  logic                   clk,
    input  logic                   rst,     // synchronous, active high
    input  logic                   wr_en,
    input  logic [W-1:0]           din,
    input  logic                   rd_en,
    output logic [W-1:0]           dout,
    output logic                   full,
    output logic                   empty,
    output logic [$clog2(DEPTH):0] count
);

    localparam int AW = $clog2(DEPTH);

    logic [W-1:0]  mem [DEPTH];
    logic [AW-1:0] wr_ptr;
    logic [AW-1:0] rd_ptr;
    logic [AW:0]   cnt;

    logic do_wr;
    logic do_rd;

    assign full  = (cnt == DEPTH[AW:0]);
    assign empty = (cnt == '0);
    assign count = cnt;

    assign do_wr = wr_en && !full;
    assign do_rd = rd_en && !empty;

    always_ff @(posedge clk) begin
        if (do_wr) begin
            mem[wr_ptr] <= din;
        end
    end

    always_ff @(posedge clk) begin
        if (rst) begin
            wr_ptr <= '0;
            rd_ptr <= '0;
            cnt    <= '0;
            dout   <= '0;
        end else begin
            if (do_wr) begin
                wr_ptr <= wr_ptr + 1'b1;
            end
            if (do_rd) begin
                rd_ptr <= rd_ptr + 1'b1;
                dout   <= mem[rd_ptr];
            end
            if (do_wr && !do_rd) begin
                cnt <= cnt + 1'b1;
            end else if (do_rd && !do_wr) begin
                cnt <= cnt - 1'b1;
            end
        end
    end

endmodule

module fifo_sync #(
    parameter int W     = 8,   // data width
    parameter int DEPTH = 8    // number of entries, a power of 2
) (
    input  logic                   clk,
    input  logic                   rst,     // synchronous, active high
    input  logic                   wr_en,
    input  logic [W-1:0]           din,
    input  logic                   rd_en,
    output logic [W-1:0]           dout,
    output logic                   full,
    output logic                   empty,
    output logic [$clog2(DEPTH):0] count
);

    localparam int AW = $clog2(DEPTH);

    logic [W-1:0]  mem [DEPTH];
    logic [AW-1:0] wptr;
    logic [AW-1:0] rptr;

    logic do_wr;
    logic do_rd;

    assign full  = (count == DEPTH[AW:0]);
    assign empty = (count == '0);

    assign do_wr = wr_en && !full;
    assign do_rd = rd_en && !empty;

    // Storage
    always_ff @(posedge clk) begin
        if (do_wr)
            mem[wptr] <= din;
    end

    // Pointers and occupancy
    always_ff @(posedge clk) begin
        if (rst) begin
            wptr  <= '0;
            rptr  <= '0;
            count <= '0;
        end else begin
            if (do_wr)
                wptr <= wptr + 1'b1;
            if (do_rd)
                rptr <= rptr + 1'b1;
            if (do_wr && !do_rd)
                count <= count + 1'b1;
            else if (do_rd && !do_wr)
                count <= count - 1'b1;
        end
    end

    // Registered read data
    always_ff @(posedge clk) begin
        if (rst)
            dout <= '0;
        else if (do_rd)
            dout <= mem[rptr];
    end

endmodule

module rr_arbiter4 (
    input  logic       clk,
    input  logic       rst,   // synchronous, active high
    input  logic [3:0] req,
    output logic [3:0] gnt
);

    logic [1:0] last, last_n;
    logic [3:0] gnt_n;
    logic [1:0] idx;

    // Combinational round-robin search. Candidates are last+1, last+2,
    // last+3, last+4 (mod 4). Iterating from lowest to highest priority
    // means the highest-priority hit (k = 1) is assigned last and wins.
    always_comb begin
        gnt_n  = 4'b0000;
        last_n = last;
        idx    = 2'd0;
        for (int k = 4; k >= 1; k--) begin
            idx = last + 2'(k);  // 2-bit arithmetic wraps mod 4
            if (req[idx]) begin
                gnt_n  = 4'b1 << idx;
                last_n = idx;
            end
        end
    end

    // Registered state and output.
    always_ff @(posedge clk) begin
        if (rst) begin
            gnt  <= 4'b0000;
            last <= 2'd3;
        end else begin
            gnt  <= gnt_n;
            last <= last_n;
        end
    end

endmodule

module rr_arbiter4 (
    input  logic       clk,
    input  logic       rst,   // synchronous, active high
    input  logic [3:0] req,
    output logic [3:0] gnt
);

    logic [1:0] last;
    logic [1:0] last_nxt;
    logic [3:0] gnt_nxt;
    logic [1:0] idx;
    logic       found;

    // Combinational next-state: round-robin search starting at last+1
    always_comb begin
        gnt_nxt  = 4'b0000;
        last_nxt = last;
        found    = 1'b0;
        idx      = last;
        if (req != 4'b0000) begin
            for (int k = 1; k <= 4; k++) begin
                idx = idx + 2'd1;          // wraps modulo 4
                if (!found && req[idx]) begin
                    found    = 1'b1;
                    gnt_nxt  = 4'b1 << idx;
                    last_nxt = idx;
                end
            end
        end
    end

    // Registered state and grant output
    always_ff @(posedge clk) begin
        if (rst) begin
            gnt  <= 4'b0000;
            last <= 2'd3;
        end else begin
            gnt  <= gnt_nxt;
            last <= last_nxt;
        end
    end

endmodule

module rr_arbiter4 (
    input  logic       clk,
    input  logic       rst,   // synchronous, active high
    input  logic [3:0] req,
    output logic [3:0] gnt
);

    logic [1:0] last;
    logic [1:0] nxt;
    logic       any_req;

    always_comb begin
        nxt     = 2'd0;
        any_req = |req;
        // Scan last+4 .. last+1; the lowest k with a request overrides the rest.
        for (int k = 4; k >= 1; k--) begin
            if (req[last + 2'(k)]) begin
                nxt = last + 2'(k);
            end
        end
    end

    always_ff @(posedge clk) begin
        if (rst) begin
            gnt  <= 4'b0;
            last <= 2'd3;
        end else if (!any_req) begin
            gnt  <= 4'b0;
        end else begin
            gnt  <= 4'b1 << nxt;
            last <= nxt;
        end
    end

endmodule

module rr_arbiter4 (
    input  logic       clk,
    input  logic       rst,   // synchronous, active high
    input  logic [3:0] req,
    output logic [3:0] gnt
);

    logic [1:0] last;
    logic [1:0] sel;
    logic       found;
    logic [1:0] idx;

    // Priority search: indices last+1, last+2, last+3, last+4 (mod 4)
    always_comb begin
        found = 1'b0;
        sel   = 2'd0;
        idx   = 2'd0;
        for (int k = 1; k <= 4; k++) begin
            idx = last + k[1:0];
            if (!found && req[idx]) begin
                found = 1'b1;
                sel   = idx;
            end
        end
    end

    always_ff @(posedge clk) begin
        if (rst) begin
            gnt  <= 4'b0000;
            last <= 2'd3;
        end else if (!found) begin
            gnt <= 4'b0000;
        end else begin
            gnt  <= 4'b1 << sel;
            last <= sel;
        end
    end

endmodule

module rr_arbiter4 (
    input  logic       clk,
    input  logic       rst,   // synchronous, active high
    input  logic [3:0] req,
    output logic [3:0] gnt
);

    logic [1:0] last;
    logic [1:0] last_n;
    logic [3:0] gnt_n;
    logic       found;
    logic [1:0] idx;

    always_comb begin
        gnt_n  = 4'b0;
        last_n = last;
        found  = 1'b0;
        idx    = 2'd0;
        for (int k = 1; k <= 4; k++) begin
            idx = last + 2'(k);
            if (!found && req[idx]) begin
                found  = 1'b1;
                gnt_n  = 4'b1 << idx;
                last_n = idx;
            end
        end
    end

    always_ff @(posedge clk) begin
        if (rst) begin
            gnt  <= 4'b0;
            last <= 2'd3;
        end else begin
            gnt  <= gnt_n;
            last <= last_n;
        end
    end

endmodule

module uart_tx #(
    parameter int CLKS_PER_BIT = 4   // clock cycles per UART bit, >= 2
) (
    input  logic       clk,
    input  logic       rst,     // synchronous, active high
    input  logic       start,
    input  logic [7:0] data,
    output logic       tx,
    output logic       busy
);

    localparam int CW = $clog2(CLKS_PER_BIT + 1);

    logic [9:0]     frame;   // {stop, data[7:0], start}
    logic [3:0]     idx;     // current bit index 0..9
    logic [CW-1:0]  cnt;     // clock cycles the current bit has been driven

    always_ff @(posedge clk) begin
        if (rst) begin
            tx    <= 1'b1;
            busy  <= 1'b0;
            frame <= 10'h3FF;
            idx   <= '0;
            cnt   <= '0;
        end else if (!busy) begin
            if (start) begin
                frame <= {1'b1, data, 1'b0};
                tx    <= 1'b0;       // start bit
                busy  <= 1'b1;
                idx   <= '0;
                cnt   <= CW'(1);
            end
        end else begin
            if (cnt == CW'(CLKS_PER_BIT)) begin
                if (idx == 4'd9) begin
                    // stop bit finished: end of frame
                    busy <= 1'b0;
                    tx   <= 1'b1;
                    idx  <= '0;
                    cnt  <= '0;
                end else begin
                    idx <= idx + 4'd1;
                    tx  <= frame[idx + 4'd1];
                    cnt <= CW'(1);
                end
            end else begin
                cnt <= cnt + CW'(1);
            end
        end
    end

endmodule

module uart_tx #(
    parameter int CLKS_PER_BIT = 4   // clock cycles per UART bit, >= 2
) (
    input  logic       clk,
    input  logic       rst,     // synchronous, active high
    input  logic       start,
    input  logic [7:0] data,
    output logic       tx,
    output logic       busy
);

    localparam int CNT_W = $clog2(CLKS_PER_BIT);

    logic [7:0]        data_q;
    logic [CNT_W-1:0]  cnt;
    logic [3:0]        idx;   // 0 = start bit, 1..8 = data bits 0..7 (idx-1), 9 = stop bit

    always_ff @(posedge clk) begin
        if (rst) begin
            tx     <= 1'b1;
            busy   <= 1'b0;
            data_q <= 8'd0;
            cnt    <= '0;
            idx    <= 4'd0;
        end else if (!busy) begin
            if (start) begin
                data_q <= data;
                tx     <= 1'b0;
                busy   <= 1'b1;
                cnt    <= '0;
                idx    <= 4'd0;
            end
        end else begin
            if (cnt == CNT_W'(CLKS_PER_BIT - 1)) begin
                cnt <= '0;
                if (idx == 4'd9) begin
                    busy <= 1'b0;
                    tx   <= 1'b1;
                    idx  <= 4'd0;
                end else begin
                    idx <= idx + 4'd1;
                    // next bit: idx 0..7 -> data bit idx; idx 8 -> stop bit
                    if (idx == 4'd8)
                        tx <= 1'b1;
                    else
                        tx <= data_q[idx[2:0]];
                end
            end else begin
                cnt <= cnt + 1'b1;
            end
        end
    end

endmodule

module uart_tx #(
    parameter int CLKS_PER_BIT = 4   // clock cycles per UART bit, >= 2
) (
    input  logic       clk,
    input  logic       rst,     // synchronous, active high
    input  logic       start,
    input  logic [7:0] data,
    output logic       tx,
    output logic       busy
);

    localparam int CNT_W = $clog2(CLKS_PER_BIT);

    logic [7:0]     data_reg;
    logic [3:0]     bit_idx;   // 0 = start, 1..8 = data[0..7], 9 = stop
    logic [CNT_W-1:0] clk_cnt;

    always_ff @(posedge clk) begin
        if (rst) begin
            tx       <= 1'b1;
            busy     <= 1'b0;
            data_reg <= 8'd0;
            bit_idx  <= 4'd0;
            clk_cnt  <= '0;
        end else if (!busy) begin
            if (start) begin
                data_reg <= data;
                tx       <= 1'b0;   // start bit
                busy     <= 1'b1;
                bit_idx  <= 4'd0;
                clk_cnt  <= '0;
            end
        end else begin
            if (clk_cnt == CNT_W'(CLKS_PER_BIT - 1)) begin
                clk_cnt <= '0;
                if (bit_idx == 4'd9) begin
                    // stop bit finished
                    busy <= 1'b0;
                    tx   <= 1'b1;
                end else begin
                    bit_idx <= bit_idx + 4'd1;
                    if (bit_idx < 4'd8)
                        tx <= data_reg[bit_idx[2:0]];  // next data bit
                    else
                        tx <= 1'b1;                    // stop bit
                end
            end else begin
                clk_cnt <= clk_cnt + CNT_W'(1);
            end
        end
    end

endmodule

module uart_tx #(
    parameter int CLKS_PER_BIT = 4   // clock cycles per UART bit, >= 2
) (
    input  logic       clk,
    input  logic       rst,     // synchronous, active high
    input  logic       start,
    input  logic [7:0] data,
    output logic       tx,
    output logic       busy
);

    localparam int CW = $clog2(CLKS_PER_BIT);

    logic [CW-1:0] clk_cnt;   // cycles elapsed within current bit
    logic [3:0]    bit_cnt;   // index of current bit (0 = start, 9 = stop)
    logic [8:0]    sh;        // remaining bits: {stop, data[7:0]}, sh[0] is next bit

    always_ff @(posedge clk) begin
        if (rst) begin
            tx      <= 1'b1;
            busy    <= 1'b0;
            clk_cnt <= '0;
            bit_cnt <= '0;
            sh      <= '0;
        end else if (!busy) begin
            if (start) begin
                tx      <= 1'b0;          // start bit
                busy    <= 1'b1;
                clk_cnt <= '0;
                bit_cnt <= '0;
                sh      <= {1'b1, data};  // data[0] next, then data[7:1], stop
            end
        end else begin
            if (clk_cnt == CW'(CLKS_PER_BIT - 1)) begin
                clk_cnt <= '0;
                if (bit_cnt == 4'd9) begin
                    // stop bit finished
                    busy    <= 1'b0;
                    tx      <= 1'b1;
                    bit_cnt <= '0;
                end else begin
                    bit_cnt <= bit_cnt + 4'd1;
                    tx      <= sh[0];
                    sh      <= {1'b1, sh[8:1]};
                end
            end else begin
                clk_cnt <= clk_cnt + CW'(1);
            end
        end
    end

endmodule

module uart_tx #(
    parameter int CLKS_PER_BIT = 4   // clock cycles per UART bit, >= 2
) (
    input  logic       clk,
    input  logic       rst,     // synchronous, active high
    input  logic       start,
    input  logic [7:0] data,
    output logic       tx,
    output logic       busy
);

    localparam int CW = (CLKS_PER_BIT > 1) ? $clog2(CLKS_PER_BIT) : 1;

    logic [CW-1:0] cnt;      // clock cycle within current bit
    logic [3:0]    idx;      // 0 = start bit, 1..8 = data bits, 9 = stop bit
    logic [7:0]    sh;       // captured data, shifted out LSB first

    always_ff @(posedge clk) begin
        if (rst) begin
            tx   <= 1'b1;
            busy <= 1'b0;
            cnt  <= '0;
            idx  <= '0;
            sh   <= '0;
        end else if (!busy) begin
            if (start) begin
                tx   <= 1'b0;        // start bit
                busy <= 1'b1;
                cnt  <= '0;
                idx  <= '0;
                sh   <= data;
            end
        end else begin
            if (cnt == CW'(CLKS_PER_BIT - 1)) begin
                cnt <= '0;
                if (idx == 4'd9) begin
                    busy <= 1'b0;
                    tx   <= 1'b1;
                    idx  <= '0;
                end else begin
                    idx <= idx + 4'd1;
                    if (idx == 4'd8) begin
                        tx <= 1'b1;  // stop bit
                    end else begin
                        tx <= sh[0];
                        sh <= {1'b0, sh[7:1]};
                    end
                end
            end else begin
                cnt <= cnt + CW'(1);
            end
        end
    end

endmodule

module noc_router5 #(
    parameter logic [1:0] X = 2'd1,
    parameter logic [1:0] Y = 2'd1,
    parameter int PAYLOAD_W = 8
) (
    input  logic                       clk,
    input  logic                       rst,
    input  logic [4:0]                 in_valid,
    output logic [4:0]                 in_ready,
    input  logic [5*(4+PAYLOAD_W)-1:0]  in_flit,
    output logic [4:0]                 out_valid,
    input  logic [4:0]                 out_ready,
    output logic [5*(4+PAYLOAD_W)-1:0]  out_flit
);

    localparam int F = 4 + PAYLOAD_W;

    // Output direction indices: N=0, S=1, E=2, W=3, L=4
    function automatic logic [2:0] route_f(input logic [1:0] dx, input logic [1:0] dy);
        if (dx > X)      return 3'd2;
        else if (dx < X) return 3'd3;
        else if (dy > Y) return 3'd0;
        else if (dy < Y) return 3'd1;
        else             return 3'd4;
    endfunction

    function automatic logic [2:0] succ(input logic [2:0] s);
        return (s == 3'd4) ? 3'd0 : (s + 3'd1);
    endfunction

    logic [4:0][F-1:0] in_f;
    logic [4:0][2:0]   rq;

    logic [4:0]           ov;
    logic [4:0][F-1:0]    oreg;
    logic [4:0][2:0]      osrc;
    logic [4:0][2:0]      cur;

    logic [4:0]           chv;
    logic [4:0][2:0]      chs;

    always_comb begin : comb
        int t;
        logic found;
        logic [2:0] st;
        for (int i = 0; i < 5; i++) begin
            in_f[i] = in_flit[i*F +: F];
            rq[i]   = route_f(in_f[i][F-1 -: 2], in_f[i][F-3 -: 2]);
        end
        in_ready = '0;
        chv      = '0;
        chs      = '0;
        for (int o = 0; o < 5; o++) begin
            st    = (ov[o] && out_ready[o]) ? succ(osrc[o]) : cur[o];
            found = 1'b0;
            for (int k = 0; k < 5; k++) begin
                t = int'(st) + k;
                if (t >= 5) t = t - 5;
                if (!found && !rst && (!ov[o] || out_ready[o]) &&
                    in_valid[t] && (rq[t] == o[2:0])) begin
                    found   = 1'b1;
                    chv[o]  = 1'b1;
                    chs[o]  = t[2:0];
                end
            end
            if (chv[o]) in_ready[chs[o]] = 1'b1;
        end
        for (int o = 0; o < 5; o++) begin
            out_flit[o*F +: F] = ov[o] ? oreg[o] : '0;
        end
    end

    assign out_valid = ov;

    always_ff @(posedge clk) begin
        for (int o = 0; o < 5; o++) begin
            if (rst) begin
                ov[o]   <= 1'b0;
                cur[o]  <= 3'd0;
                osrc[o] <= 3'd0;
                oreg[o] <= '0;
            end else begin
                if (ov[o] && out_ready[o])
                    cur[o] <= succ(osrc[o]);
                if (chv[o]) begin
                    ov[o]   <= 1'b1;
                    oreg[o] <= in_f[chs[o]];
                    osrc[o] <= chs[o];
                end else if (out_ready[o]) begin
                    ov[o] <= 1'b0;
                end
            end
        end
    end

endmodule

module noc_router5 #(
    parameter logic [1:0] X = 2'd1,
    parameter logic [1:0] Y = 2'd1,
    parameter int PAYLOAD_W = 8
) (
    input  logic                       clk,
    input  logic                       rst,
    input  logic [4:0]                 in_valid,
    output logic [4:0]                 in_ready,
    input  logic [5*(4+PAYLOAD_W)-1:0]  in_flit,
    output logic [4:0]                 out_valid,
    input  logic [4:0]                 out_ready,
    output logic [5*(4+PAYLOAD_W)-1:0]  out_flit
);

    localparam int F = 4 + PAYLOAD_W;

    // Direction indices: N=0, S=1, E=2, W=3, L=4
    function automatic logic [2:0] route_f(input logic [1:0] dx, input logic [1:0] dy);
        if (dx > X)      return 3'd2;
        else if (dx < X) return 3'd3;
        else if (dy > Y) return 3'd0;
        else if (dy < Y) return 3'd1;
        else             return 3'd4;
    endfunction

    function automatic logic [2:0] succ(input logic [2:0] s);
        return (s == 3'd4) ? 3'd0 : (s + 3'd1);
    endfunction

    logic [4:0][F-1:0] in_f;
    logic [4:0][2:0]   rq;
    logic [4:0]        ov;
    logic [4:0][F-1:0] oreg;
    logic [4:0][2:0]   osrc;
    logic [4:0][2:0]   cur;
    logic [4:0]        avail;
    logic [4:0]        chv;
    logic [4:0][2:0]   chs;

    genvar g;
    generate
        for (g = 0; g < 5; g++) begin : g_out
            localparam logic [2:0] ID = 3'(g);

            logic           ov_r;
            logic [F-1:0]   oreg_r;
            logic [2:0]     osrc_r;
            logic [2:0]     cur_r;
            logic           avail_l;
            logic [2:0]     st;
            logic           found;
            logic           chv_l;
            logic [2:0]     chs_l;

            assign in_f[g]            = in_flit[g*F +: F];
            assign rq[g]              = route_f(in_f[g][F-1 -: 2], in_f[g][F-3 -: 2]);
            assign out_flit[g*F +: F] = ov_r ? oreg_r : '0;
            assign ov[g]              = ov_r;
            assign oreg[g]            = oreg_r;
            assign osrc[g]            = osrc_r;
            assign cur[g]             = cur_r;
            assign avail[g]           = avail_l;
            assign chv[g]             = chv_l;
            assign chs[g]             = chs_l;
            assign out_valid[g]       = ov_r;

            assign avail_l = ~ov_r | out_ready[g];

            always_comb begin : arb
                integer t;
                st    = (ov_r && out_ready[g]) ? succ(osrc_r) : cur_r;
                found = 1'b0;
                chv_l = 1'b0;
                chs_l = 3'd0;
                for (int k = 0; k < 5; k++) begin
                    t = int'(st) + k;
                    if (t >= 5) t = t - 5;
                    if (!found && !rst && avail_l && in_valid[t] && (rq[t] == ID)) begin
                        found = 1'b1;
                        chv_l = 1'b1;
                        chs_l = 3'(t);
                    end
                end
            end

            always_ff @(posedge clk) begin
                if (rst) begin
                    ov_r   <= 1'b0;
                    cur_r  <= 3'd0;
                    osrc_r <= 3'd0;
                    oreg_r <= '0;
                end else begin
                    if (ov_r && out_ready[g])
                        cur_r <= succ(osrc_r);
                    if (chv_l) begin
                        ov_r   <= 1'b1;
                        oreg_r <= in_f[chs_l];
                        osrc_r <= chs_l;
                    end else if (out_ready[g]) begin
                        ov_r <= 1'b0;
                    end
                end
            end
        end
    endgenerate

    always_comb begin : ready_comb
        in_ready = '0;
        for (int o = 0; o < 5; o++) begin
            if (chv[o]) in_ready[chs[o]] = 1'b1;
        end
    end

endmodule

module noc_router5 #(
    parameter logic [1:0] X = 2'd1,
    parameter logic [1:0] Y = 2'd1,
    parameter int PAYLOAD_W = 8
) (
    input  logic                       clk,
    input  logic                       rst,
    input  logic [4:0]                 in_valid,
    output logic [4:0]                 in_ready,
    input  logic [5*(4+PAYLOAD_W)-1:0]  in_flit,
    output logic [4:0]                 out_valid,
    input  logic [4:0]                 out_ready,
    output logic [5*(4+PAYLOAD_W)-1:0]  out_flit
);

    localparam int F = 4 + PAYLOAD_W;

    // Slot state
    logic            sv   [5];
    logic [F-1:0]    sf   [5];
    logic [2:0]      ssrc [5];
    logic [2:0]      cur  [5];

    // Request computation
    logic [2:0] req [5];
    logic [1:0] dx  [5];
    logic [1:0] dy  [5];

    always_comb begin
        for (int i = 0; i < 5; i++) begin
            dx[i] = in_flit[i*F + F - 1 -: 2];
            dy[i] = in_flit[i*F + F - 3 -: 2];
            if (dx[i] > X)      req[i] = 3'd2; // E
            else if (dx[i] < X) req[i] = 3'd3; // W
            else if (dy[i] > Y) req[i] = 3'd0; // N
            else if (dy[i] < Y) req[i] = 3'd1; // S
            else                req[i] = 3'd4; // L
        end
    end

    // Arbitration
    logic       avail [5];
    logic [2:0] start [5];
    logic       has   [5];
    logic [2:0] win   [5];
    logic       acc   [5];

    function automatic logic [2:0] succ(input logic [2:0] s);
        return (s == 3'd4) ? 3'd0 : s + 3'd1;
    endfunction

    always_comb begin
        for (int o = 0; o < 5; o++) begin
            avail[o] = !sv[o] || out_ready[o];
            start[o] = sv[o] ? succ(ssrc[o]) : cur[o];
            has[o]   = 1'b0;
            win[o]   = 3'd0;
            for (int k = 0; k < 5; k++) begin
                int idx;
                idx = (int'(start[o]) + k) % 5;
                if (!has[o] && in_valid[idx] && (req[idx] == 3'(o))) begin
                    has[o] = 1'b1;
                    win[o] = 3'(idx);
                end
            end
            acc[o] = avail[o] && has[o];
        end
    end

    // Input ready
    always_comb begin
        for (int i = 0; i < 5; i++) begin
            in_ready[i] = !rst && in_valid[i] && avail[req[i]] &&
                          has[req[i]] && (win[req[i]] == 3'(i));
        end
    end

    // Output drive
    always_comb begin
        for (int o = 0; o < 5; o++) begin
            out_valid[o] = sv[o];
            out_flit[o*F +: F] = sv[o] ? sf[o] : '0;
        end
    end

    // Sequential state
    always_ff @(posedge clk) begin
        if (rst) begin
            for (int o = 0; o < 5; o++) begin
                sv[o]   <= 1'b0;
                sf[o]   <= '0;
                ssrc[o] <= 3'd0;
                cur[o]  <= 3'd0;
            end
        end else begin
            for (int o = 0; o < 5; o++) begin
                if (acc[o]) begin
                    sv[o]   <= 1'b1;
                    sf[o]   <= in_flit[win[o]*F +: F];
                    ssrc[o] <= win[o];
                end else if (out_ready[o]) begin
                    sv[o] <= 1'b0;
                end
                if (sv[o] && out_ready[o]) begin
                    cur[o] <= succ(ssrc[o]);
                end
            end
        end
    end

endmodule

module noc_router5 #(
    parameter logic [1:0] X = 2'd1,
    parameter logic [1:0] Y = 2'd1,
    parameter int PAYLOAD_W = 8
) (
    input  logic                       clk,
    input  logic                       rst,
    input  logic [4:0]                 in_valid,
    output logic [4:0]                 in_ready,
    input  logic [5*(4+PAYLOAD_W)-1:0]  in_flit,
    output logic [4:0]                 out_valid,
    input  logic [4:0]                 out_ready,
    output logic [5*(4+PAYLOAD_W)-1:0]  out_flit
);

    localparam int F = 4 + PAYLOAD_W;

    // Registered output slots and cursors (packed; 3 bits per lane)
    logic [4:0]         sv;
    logic [5*F-1:0]     sf;
    logic [14:0]        ssrc;
    logic [14:0]        cur;

    // Per-input requested output (3 bits per input)
    logic [14:0]        req;

    // Per-output arbitration results
    logic [4:0]         avail;
    logic [4:0]         acc;
    logic [14:0]        win;
    logic [4:0]         c_t;

    // Successor in cyclic order N,S,E,W,L
    function automatic logic [2:0] succ3(input logic [2:0] s);
        return (s == 3'd4) ? 3'd0 : s + 3'd1;
    endfunction

    // Cyclic scan from start s over candidate mask c.
    // Returns {found, index}.
    function automatic logic [3:0] pick(input logic [4:0] c, input logic [2:0] s);
        logic [3:0] r;
        logic [3:0] t;
        logic [2:0] j;
        r = 4'd0;
        for (int k = 4; k >= 0; k--) begin
            t = {1'b0, s} + 4'(k);
            if (t >= 4'd5) t = t - 4'd5;
            j = t[2:0];
            if (c[j]) r = {1'b1, j};
        end
        return r;
    endfunction

    // Routing
    always_comb begin
        for (int i = 0; i < 5; i++) begin
            if (in_flit[i*F + F - 1 -: 2] > X)
                req[i*3 +: 3] = 3'd2; // E
            else if (in_flit[i*F + F - 1 -: 2] < X)
                req[i*3 +: 3] = 3'd3; // W
            else if (in_flit[i*F + F - 3 -: 2] > Y)
                req[i*3 +: 3] = 3'd0; // N
            else if (in_flit[i*F + F - 3 -: 2] < Y)
                req[i*3 +: 3] = 3'd1; // S
            else
                req[i*3 +: 3] = 3'd4; // L
        end
    end

    // Arbitration and input ready
    always_comb begin
        logic [3:0] pr;
        logic [2:0] st;
        in_ready = 5'd0;
        for (int o = 0; o < 5; o++) begin
            c_t = 5'd0;
            for (int i = 0; i < 5; i++) begin
                c_t[i] = in_valid[i] && (req[i*3 +: 3] == 3'(o));
            end
            st = sv[o] ? succ3(ssrc[o*3 +: 3]) : cur[o*3 +: 3];
            pr = pick(c_t, st);
            avail[o] = !sv[o] || out_ready[o];
            acc[o] = avail[o] && pr[3];
            win[o*3 +: 3] = pr[2:0];
            if (acc[o] && !rst)
                in_ready[pr[2:0]] = 1'b1;
        end
    end

    // Output drive
    always_comb begin
        for (int o = 0; o < 5; o++) begin
            out_valid[o] = sv[o];
            out_flit[o*F +: F] = sv[o] ? sf[o*F +: F] : '0;
        end
    end

    // Sequential state
    always_ff @(posedge clk) begin
        if (rst) begin
            sv   <= 5'd0;
            ssrc <= 15'd0;
            cur  <= 15'd0;
        end else begin
            for (int o = 0; o < 5; o++) begin
                if (acc[o]) begin
                    sv[o] <= 1'b1;
                    sf[o*F +: F] <= in_flit[win[o*3 +: 3]*F +: F];
                    ssrc[o*3 +: 3] <= win[o*3 +: 3];
                end else if (out_ready[o]) begin
                    sv[o] <= 1'b0;
                end
                if (sv[o] && out_ready[o])
                    cur[o*3 +: 3] <= succ3(ssrc[o*3 +: 3]);
            end
        end
    end

endmodule

module noc_router5 #(
    parameter logic [1:0] X = 2'd1,
    parameter logic [1:0] Y = 2'd1,
    parameter int PAYLOAD_W = 8
) (
    input  logic                        clk,
    input  logic                        rst,
    input  logic [4:0]                  in_valid,
    output logic [4:0]                  in_ready,
    input  logic [5*(4+PAYLOAD_W)-1:0]  in_flit,
    output logic [4:0]                  out_valid,
    input  logic [4:0]                  out_ready,
    output logic [5*(4+PAYLOAD_W)-1:0]  out_flit
);

    localparam int F = 4 + PAYLOAD_W;

    // Registered output slots
    logic [4:0]   ovalid;
    logic [F-1:0] oflit [5];
    logic [2:0]   src    [5];   // source index of flit currently in slot
    logic [2:0]   cursor [5];   // scan start when slot is empty

    // Combinational signals
    logic [F-1:0] inf   [5];
    logic [2:0]   req   [5];
    logic [4:0]   avail;
    logic [2:0]   start [5];
    logic [4:0]   cv;
    logic [2:0]   cs    [5];

    function automatic logic [2:0] succ(input logic [2:0] s);
        return (s == 3'd4) ? 3'd0 : (s + 3'd1);
    endfunction

    // Routing computation
    always_comb begin
        for (int i = 0; i < 5; i++) begin
            logic [1:0] dx;
            logic [1:0] dy;
            inf[i] = in_flit[i*F +: F];
            dx = inf[i][F-1 -: 2];
            dy = inf[i][F-3 -: 2];
            if (dx > X)       req[i] = 3'd2; // E
            else if (dx < X)  req[i] = 3'd3; // W
            else if (dy > Y)  req[i] = 3'd0; // N
            else if (dy < Y)  req[i] = 3'd1; // S
            else              req[i] = 3'd4; // L
        end
    end

    // Arbitration
    always_comb begin
        in_ready = '0;
        avail    = '0;
        cv       = '0;
        for (int o = 0; o < 5; o++) begin
            cs[o]    = 3'd0;
            start[o] = ovalid[o] ? succ(src[o]) : cursor[o];
            avail[o] = !rst && (!ovalid[o] || out_ready[o]);
            if (avail[o]) begin
                for (int k = 0; k < 5; k++) begin
                    int t;
                    int idx;
                    t = int'(start[o]) + k;
                    if (t >= 5) t = t - 5;
                    idx = t;
                    if (!cv[o] && in_valid[idx] && (req[idx] == 3'(o))) begin
                        cv[o] = 1'b1;
                        cs[o] = 3'(idx);
                    end
                end
            end
            if (cv[o]) in_ready[cs[o]] = 1'b1;
        end
    end

    // Sequential state
    always_ff @(posedge clk) begin
        if (rst) begin
            ovalid <= '0;
            for (int o = 0; o < 5; o++) begin
                oflit[o]  <= '0;
                src[o]    <= 3'd0;
                cursor[o] <= 3'd0;
            end
        end else begin
            for (int o = 0; o < 5; o++) begin
                if (avail[o]) begin
                    if (cv[o]) begin
                        ovalid[o] <= 1'b1;
                        oflit[o]  <= inf[cs[o]];
                        src[o]    <= cs[o];
                    end else begin
                        ovalid[o] <= 1'b0;
                    end
                end
                if (ovalid[o] && out_ready[o]) begin
                    cursor[o] <= succ(src[o]);
                end
            end
        end
    end

    // Outputs
    assign out_valid = ovalid;

    always_comb begin
        for (int o = 0; o < 5; o++) begin
            out_flit[o*F +: F] = ovalid[o] ? oflit[o] : '0;
        end
    end

endmodule

module noc_router5 #(
    parameter logic [1:0] X = 2'd1,
    parameter logic [1:0] Y = 2'd1,
    parameter int PAYLOAD_W = 8
) (
    input  logic                         clk,
    input  logic                         rst,
    input  logic [4:0]                   in_valid,
    output logic [4:0]                   in_ready,
    input  logic [5*(4+PAYLOAD_W)-1:0]   in_flit,
    output logic [4:0]                   out_valid,
    input  logic [4:0]                   out_ready,
    output logic [5*(4+PAYLOAD_W)-1:0]   out_flit
);

    localparam int F = 4 + PAYLOAD_W;

    // Output slot state
    logic [4:0]    ov;
    logic [F-1:0]  sf  [5];
    logic [2:0]    src [5];
    logic [2:0]    cur [5];

    // Combinational arbitration state
    logic [2:0]    req   [5];
    logic [4:0]    avail;
    logic [2:0]    ec    [5];
    logic [4:0]    wfound;
    logic [2:0]    win   [5];
    logic [4:0]    gnt;

    function automatic logic [2:0] succ(input logic [2:0] s);
        return (s == 3'd4) ? 3'd0 : (s + 3'd1);
    endfunction

    always_comb begin
        logic [1:0] dx;
        logic [1:0] dy;
        int         idx;
        int         ecv;

        // Routing for each input lane
        for (int i = 0; i < 5; i++) begin
            dx = in_flit[i*F + F - 1 -: 2];
            dy = in_flit[i*F + F - 3 -: 2];
            if (dx > X)       req[i] = 3'd2; // E
            else if (dx < X)  req[i] = 3'd3; // W
            else if (dy > Y)  req[i] = 3'd0; // N
            else if (dy < Y)  req[i] = 3'd1; // S
            else              req[i] = 3'd4; // L
        end

        // Availability and effective cursor per output
        for (int o = 0; o < 5; o++) begin
            avail[o] = ~ov[o] | out_ready[o];
            if (ov[o] & out_ready[o])
                ec[o] = succ(src[o]);
            else
                ec[o] = cur[o];
        end

        // Winner selection per output (cyclic scan from effective cursor)
        for (int o = 0; o < 5; o++) begin
            wfound[o] = 1'b0;
            win[o]    = 3'd0;
            ecv       = int'(ec[o]);
            for (int k = 0; k < 5; k++) begin
                idx = ecv + k;
                if (idx >= 5) idx = idx - 5;
                if (!wfound[o] && avail[o] && in_valid[idx] && (int'(req[idx]) == o)) begin
                    wfound[o] = 1'b1;
                    win[o]    = 3'(idx);
                end
            end
        end

        // Per-input grant
        for (int i = 0; i < 5; i++) begin
            gnt[i] = 1'b0;
            for (int o = 0; o < 5; o++) begin
                if (wfound[o] && (int'(win[o]) == i))
                    gnt[i] = 1'b1;
            end
        end
    end

    assign in_ready = gnt & {5{~rst}};

    // Output driving
    always_comb begin
        for (int o = 0; o < 5; o++) begin
            out_flit[o*F +: F] = ov[o] ? sf[o] : {F{1'b0}};
        end
    end

    assign out_valid = ov;

    // Sequential state
    always_ff @(posedge clk) begin
        if (rst) begin
            ov <= '0;
            for (int o = 0; o < 5; o++) begin
                cur[o] <= 3'd0;
                src[o] <= 3'd0;
            end
        end else begin
            for (int o = 0; o < 5; o++) begin
                if (avail[o]) begin
                    if (wfound[o]) begin
                        ov[o]  <= 1'b1;
                        sf[o]  <= in_flit[int'(win[o])*F +: F];
                        src[o] <= win[o];
                    end else begin
                        ov[o] <= 1'b0;
                    end
                end
                cur[o] <= ec[o];
            end
        end
    end

endmodule

module noc_router5 #(
    parameter logic [1:0] X = 2'd1,
    parameter logic [1:0] Y = 2'd1,
    parameter int PAYLOAD_W = 8
) (
    input  logic                       clk,
    input  logic                       rst,
    input  logic [4:0]                 in_valid,
    output logic [4:0]                 in_ready,
    input  logic [5*(4+PAYLOAD_W)-1:0]  in_flit,
    output logic [4:0]                 out_valid,
    input  logic [4:0]                 out_ready,
    output logic [5*(4+PAYLOAD_W)-1:0]  out_flit
);

    localparam int F = 4 + PAYLOAD_W;

    // Lane / output indices: 0=N 1=S 2=E 3=W 4=L
    logic [4:0]     valid_q;
    logic [F-1:0]   flit_q [5];
    logic [2:0]     src_q  [5];
    logic [2:0]     cur_q  [5];

    logic [F-1:0]   in_f  [5];
    logic [2:0]     route [5];
    logic [4:0]     req   [5];
    logic [2:0]     eff_cur [5];
    logic           avail [5];
    logic           gv    [5];
    logic [2:0]     chosen [5];

    function automatic logic [2:0] succ(input logic [2:0] k);
        return (k == 3'd4) ? 3'd0 : k + 3'd1;
    endfunction

    always_comb begin
        int t;
        logic [1:0] dx, dy;
        logic [4:0] ir;

        // Unpack inputs and compute routes
        for (int i = 0; i < 5; i++) begin
            in_f[i] = in_flit[i*F +: F];
            dx = in_f[i][F-1 -: 2];
            dy = in_f[i][F-3 -: 2];
            if (dx > X)       route[i] = 3'd2; // E
            else if (dx < X)  route[i] = 3'd3; // W
            else if (dy > Y)  route[i] = 3'd0; // N
            else if (dy < Y)  route[i] = 3'd1; // S
            else              route[i] = 3'd4; // L
        end

        // Per-output arbitration
        for (int o = 0; o < 5; o++) begin
            avail[o] = !valid_q[o] || out_ready[o];
            if (valid_q[o] && out_ready[o])
                eff_cur[o] = succ(src_q[o]);
            else
                eff_cur[o] = cur_q[o];

            for (int i = 0; i < 5; i++)
                req[o][i] = in_valid[i] && (route[i] == 3'(o));

            gv[o]     = 1'b0;
            chosen[o] = 3'd0;
            if (avail[o]) begin
                for (int k = 0; k < 5; k++) begin
                    t = int'(eff_cur[o]) + k;
                    if (t >= 5) t = t - 5;
                    if (!gv[o] && req[o][t]) begin
                        gv[o]     = 1'b1;
                        chosen[o] = 3'(t);
                    end
                end
            end
        end

        // Input ready: only the chosen input of each output
        for (int i = 0; i < 5; i++) begin
            ir[i] = 1'b0;
            for (int o = 0; o < 5; o++) begin
                if (gv[o] && (chosen[o] == 3'(i)))
                    ir[i] = 1'b1;
            end
        end
        in_ready = rst ? 5'b0 : ir;
    end

    // Registered outputs
    always_comb begin
        out_valid = valid_q;
        for (int o = 0; o < 5; o++) begin
            out_flit[o*F +: F] = valid_q[o] ? flit_q[o] : '0;
        end
    end

    // State update
    always_ff @(posedge clk) begin
        if (rst) begin
            valid_q <= 5'b0;
            for (int o = 0; o < 5; o++) begin
                cur_q[o] <= 3'd0;
                src_q[o] <= 3'd0;
            end
        end else begin
            for (int o = 0; o < 5; o++) begin
                if (avail[o]) begin
                    if (gv[o]) begin
                        valid_q[o] <= 1'b1;
                        flit_q[o]  <= in_f[chosen[o]];
                        src_q[o]   <= chosen[o];
                    end else begin
                        valid_q[o] <= 1'b0;
                    end
                end
                cur_q[o] <= eff_cur[o];
            end
        end
    end

endmodule

module axil_regs (
    input  logic        clk,
    input  logic        rst,
    input  logic [31:0] status_in,
    input  logic [31:0] irq_set,

    input  logic [3:0]  s_axi_awaddr,
    input  logic [2:0]  s_axi_awprot,
    input  logic        s_axi_awvalid,
    output logic        s_axi_awready,

    input  logic [31:0] s_axi_wdata,
    input  logic [3:0]  s_axi_wstrb,
    input  logic        s_axi_wvalid,
    output logic        s_axi_wready,

    output logic [1:0]  s_axi_bresp,
    output logic        s_axi_bvalid,
    input  logic        s_axi_bready,

    input  logic [3:0]  s_axi_araddr,
    input  logic [2:0]  s_axi_arprot,
    input  logic        s_axi_arvalid,
    output logic        s_axi_arready,

    output logic [31:0] s_axi_rdata,
    output logic [1:0]  s_axi_rresp,
    output logic        s_axi_rvalid,
    input  logic        s_axi_rready
);

    // Write address and data one-entry slots
    logic        aw_v;
    logic [3:0]  aw_a;
    logic        w_v;
    logic [31:0] w_d;
    logic [3:0]  w_s;

    // Register state
    logic [31:0] ctrl;
    logic [31:0] scratch;
    logic [31:0] irq;

    // Ready signals (combinational from state)
    assign s_axi_awready = !aw_v && !s_axi_bvalid && !rst;
    assign s_axi_wready  = !w_v  && !s_axi_bvalid && !rst;
    assign s_axi_arready = !s_axi_rvalid && !rst;

    wire aw_hs  = s_axi_awvalid && s_axi_awready;
    wire w_hs   = s_axi_wvalid  && s_axi_wready;
    wire ar_hs  = s_axi_arvalid && s_axi_arready;
    wire commit = aw_v && w_v;

    // Byte mask expanded from write strobes of the stored write data
    logic [31:0] wmask;
    always_comb begin
        for (int i = 0; i < 4; i++) begin
            wmask[8*i +: 8] = {8{w_s[i]}};
        end
    end

    wire aligned  = (aw_a[1:0] == 2'b00);
    wire wr_ok    = commit && aligned && (aw_a[3:2] != 2'd1); // STATUS rejected
    wire is_irq_w = (aw_a[3:2] == 2'd3);

    wire [31:0] irq_clr = (wr_ok && is_irq_w) ? (w_d & wmask) : 32'd0;

    // Read data selection (uses old register state)
    logic [31:0] rd_val;
    logic [1:0]  rd_resp;
    always_comb begin
        rd_val  = 32'd0;
        rd_resp = 2'b10;
        if (ar_hs_addr_ok(s_axi_araddr)) begin
            rd_resp = 2'b00;
            case (s_axi_araddr[3:2])
                2'd0: rd_val = ctrl;
                2'd1: rd_val = status_in;
                2'd2: rd_val = scratch;
                2'd3: rd_val = irq;
                default: rd_val = 32'd0;
            endcase
        end
    end

    function automatic logic ar_hs_addr_ok(input logic [3:0] a);
        ar_hs_addr_ok = (a[1:0] == 2'b00);
    endfunction

    always_ff @(posedge clk) begin
        if (rst) begin
            aw_v          <= 1'b0;
            aw_a          <= 4'd0;
            w_v           <= 1'b0;
            w_d           <= 32'd0;
            w_s           <= 4'd0;
            ctrl          <= 32'd0;
            scratch       <= 32'd0;
            irq           <= 32'd0;
            s_axi_bvalid  <= 1'b0;
            s_axi_bresp   <= 2'b00;
            s_axi_rvalid  <= 1'b0;
            s_axi_rdata   <= 32'd0;
            s_axi_rresp   <= 2'b00;
        end else begin
            // Write address slot
            if (aw_hs) begin
                aw_v <= 1'b1;
                aw_a <= s_axi_awaddr;
            end else if (commit) begin
                aw_v <= 1'b0;
            end

            // Write data slot
            if (w_hs) begin
                w_v <= 1'b1;
                w_d <= s_axi_wdata;
                w_s <= s_axi_wstrb;
            end else if (commit) begin
                w_v <= 1'b0;
            end

            // Write commit and B channel
            if (commit) begin
                s_axi_bvalid <= 1'b1;
                s_axi_bresp  <= wr_ok ? 2'b00 : 2'b10;
            end else if (s_axi_bvalid && s_axi_bready) begin
                s_axi_bvalid <= 1'b0;
            end

            if (wr_ok && !is_irq_w) begin
                if (aw_a[3:2] == 2'd0)
                    ctrl <= (ctrl & ~wmask) | (w_d & wmask);
                else if (aw_a[3:2] == 2'd2)
                    scratch <= (scratch & ~wmask) | (w_d & wmask);
            end

            // IRQ: clear on write commit, set from irq_set every non-reset edge
            irq <= (irq & ~irq_clr) | irq_set;

            // Read channel
            if (ar_hs) begin
                s_axi_rvalid <= 1'b1;
                s_axi_rdata  <= rd_val;
                s_axi_rresp  <= rd_resp;
            end else if (s_axi_rvalid && s_axi_rready) begin
                s_axi_rvalid <= 1'b0;
            end
        end
    end

endmodule

module axil_regs (
    input  logic        clk,
    input  logic        rst,
    input  logic [31:0] status_in,
    input  logic [31:0] irq_set,

    input  logic [3:0]  s_axi_awaddr,
    input  logic [2:0]  s_axi_awprot,
    input  logic        s_axi_awvalid,
    output logic        s_axi_awready,

    input  logic [31:0] s_axi_wdata,
    input  logic [3:0]  s_axi_wstrb,
    input  logic        s_axi_wvalid,
    output logic        s_axi_wready,

    output logic [1:0]  s_axi_bresp,
    output logic        s_axi_bvalid,
    input  logic        s_axi_bready,

    input  logic [3:0]  s_axi_araddr,
    input  logic [2:0]  s_axi_arprot,
    input  logic        s_axi_arvalid,
    output logic        s_axi_arready,

    output logic [31:0] s_axi_rdata,
    output logic [1:0]  s_axi_rresp,
    output logic        s_axi_rvalid,
    input  logic        s_axi_rready
);

    // Write-side slots
    logic        aw_v;
    logic [3:0]  aw_addr;
    logic        w_v;
    logic [31:0] w_data;
    logic [3:0]  w_strb;

    // Register state
    logic [31:0] ctrl_q;
    logic [31:0] scratch_q;
    logic [31:0] irq_q;

    // Ready signals
    assign s_axi_awready = !aw_v && !s_axi_bvalid && !rst;
    assign s_axi_wready  = !w_v  && !s_axi_bvalid && !rst;
    assign s_axi_arready = !s_axi_rvalid && !rst;

    // Commit logic
    wire        commit   = aw_v && w_v;
    wire [31:0] wmask    = {{8{w_strb[3]}}, {8{w_strb[2]}}, {8{w_strb[1]}}, {8{w_strb[0]}}};
    wire        aligned_w = (aw_addr[1:0] == 2'b00);
    wire        wr_ctrl  = commit && aligned_w && (aw_addr[3:2] == 2'd0);
    wire        wr_stat  = commit && aligned_w && (aw_addr[3:2] == 2'd1);
    wire        wr_scr   = commit && aligned_w && (aw_addr[3:2] == 2'd2);
    wire        wr_irq   = commit && aligned_w && (aw_addr[3:2] == 2'd3);
    wire        wr_ok    = wr_ctrl || wr_scr || wr_irq;

    // Read data mux (uses current, old register state)
    logic [31:0] rd_val;
    logic [1:0]  rd_resp;
    always_comb begin
        rd_val  = 32'd0;
        rd_resp = 2'b10;
        if (s_axi_araddr[1:0] == 2'b00) begin
            rd_resp = 2'b00;
            case (s_axi_araddr[3:2])
                2'd0: rd_val = ctrl_q;
                2'd1: rd_val = status_in;
                2'd2: rd_val = scratch_q;
                2'd3: rd_val = irq_q;
                default: rd_val = 32'd0;
            endcase
        end
    end

    always_ff @(posedge clk) begin
        if (rst) begin
            aw_v          <= 1'b0;
            aw_addr       <= 4'd0;
            w_v           <= 1'b0;
            w_data        <= 32'd0;
            w_strb        <= 4'd0;
            ctrl_q        <= 32'd0;
            scratch_q     <= 32'd0;
            irq_q         <= 32'd0;
            s_axi_bvalid  <= 1'b0;
            s_axi_bresp   <= 2'b00;
            s_axi_rvalid  <= 1'b0;
            s_axi_rdata   <= 32'd0;
            s_axi_rresp   <= 2'b00;
        end else begin
            // AW slot
            if (s_axi_awvalid && s_axi_awready) begin
                aw_v    <= 1'b1;
                aw_addr <= s_axi_awaddr;
            end else if (commit) begin
                aw_v    <= 1'b0;
            end

            // W slot
            if (s_axi_wvalid && s_axi_wready) begin
                w_v    <= 1'b1;
                w_data <= s_axi_wdata;
                w_strb <= s_axi_wstrb;
            end else if (commit) begin
                w_v    <= 1'b0;
            end

            // Register writes at commit
            if (wr_ctrl)
                ctrl_q <= (w_data & wmask) | (ctrl_q & ~wmask);
            if (wr_scr)
                scratch_q <= (w_data & wmask) | (scratch_q & ~wmask);

            // IRQ: clear by written 1s on enabled bytes, then OR in set pulses
            if (wr_irq)
                irq_q <= ((irq_q & ~(w_data & wmask)) | irq_set);
            else
                irq_q <= irq_q | irq_set;

            // B channel
            if (commit) begin
                s_axi_bvalid <= 1'b1;
                s_axi_bresp  <= wr_ok ? 2'b00 : 2'b10;
            end else if (s_axi_bvalid && s_axi_bready) begin
                s_axi_bvalid <= 1'b0;
            end

            // R channel
            if (s_axi_arvalid && s_axi_arready) begin
                s_axi_rvalid <= 1'b1;
                s_axi_rdata  <= rd_val;
                s_axi_rresp  <= rd_resp;
            end else if (s_axi_rvalid && s_axi_rready) begin
                s_axi_rvalid <= 1'b0;
            end
        end
    end

endmodule

module axil_regs (
    input  logic        clk,
    input  logic        rst,
    input  logic [31:0] status_in,
    input  logic [31:0] irq_set,

    input  logic [3:0]  s_axi_awaddr,
    input  logic [2:0]  s_axi_awprot,
    input  logic        s_axi_awvalid,
    output logic        s_axi_awready,

    input  logic [31:0] s_axi_wdata,
    input  logic [3:0]  s_axi_wstrb,
    input  logic        s_axi_wvalid,
    output logic        s_axi_wready,

    output logic [1:0]  s_axi_bresp,
    output logic        s_axi_bvalid,
    input  logic        s_axi_bready,

    input  logic [3:0]  s_axi_araddr,
    input  logic [2:0]  s_axi_arprot,
    input  logic        s_axi_arvalid,
    output logic        s_axi_arready,

    output logic [31:0] s_axi_rdata,
    output logic [1:0]  s_axi_rresp,
    output logic        s_axi_rvalid,
    input  logic        s_axi_rready
);

    localparam logic [1:0] RESP_OKAY   = 2'b00;
    localparam logic [1:0] RESP_SLVERR = 2'b10;

    // Write slots
    logic        aw_full;
    logic [3:0]  aw_addr;
    logic        w_full;
    logic [31:0] w_data;
    logic [3:0]  w_strb;

    // Registers
    logic [31:0] ctrl;
    logic [31:0] scratch;
    logic [31:0] irq;

    // Response state
    logic        bvalid;
    logic [1:0]  bresp;
    logic        rvalid;
    logic [31:0] rdata;
    logic [1:0]  rresp;

    // Handshake-side combinational ready
    assign s_axi_awready = !rst && !aw_full && !bvalid;
    assign s_axi_wready  = !rst && !w_full  && !bvalid;
    assign s_axi_arready = !rst && !rvalid;

    assign s_axi_bvalid = bvalid;
    assign s_axi_bresp  = bresp;
    assign s_axi_rvalid = rvalid;
    assign s_axi_rdata  = rdata;
    assign s_axi_rresp  = rresp;

    wire aw_hs   = s_axi_awvalid && s_axi_awready;
    wire w_hs    = s_axi_wvalid  && s_axi_wready;
    wire ar_hs   = s_axi_arvalid && s_axi_arready;
    wire commit  = aw_full && w_full;

    // Write address validity: aligned and one of CTRL(0), SCRATCH(8), IRQ(C)
    wire wr_aligned = (aw_addr[1:0] == 2'b00);
    wire wr_ok      = wr_aligned && (aw_addr[3:2] != 2'b01);

    wire [31:0] wmask = {{8{w_strb[3]}}, {8{w_strb[2]}}, {8{w_strb[1]}}, {8{w_strb[0]}}};
    wire [31:0] merged_ctrl    = (ctrl    & ~wmask) | (w_data & wmask);
    wire [31:0] merged_scratch = (scratch & ~wmask) | (w_data & wmask);

    wire [31:0] irq_clr = (commit && wr_ok && (aw_addr[3:2] == 2'b11)) ? (w_data & wmask) : 32'd0;

    // Read mux (old state, STATUS sampled at AR handshake)
    wire rd_aligned = (s_axi_araddr[1:0] == 2'b00);
    logic [31:0] rd_mux;
    always_comb begin
        case (s_axi_araddr[3:2])
            2'b00:   rd_mux = ctrl;
            2'b01:   rd_mux = status_in;
            2'b10:   rd_mux = scratch;
            default: rd_mux = irq;
        endcase
    end

    always_ff @(posedge clk) begin
        if (rst) begin
            aw_full <= 1'b0;
            aw_addr <= 4'd0;
            w_full  <= 1'b0;
            w_data  <= 32'd0;
            w_strb  <= 4'd0;
            ctrl    <= 32'd0;
            scratch <= 32'd0;
            irq     <= 32'd0;
            bvalid  <= 1'b0;
            bresp   <= 2'b00;
            rvalid  <= 1'b0;
            rdata   <= 32'd0;
            rresp   <= 2'b00;
        end else begin
            // IRQ: set always ORed, clear on IRQ write commit
            irq <= (irq & ~irq_clr) | irq_set;

            // Write channel slots and commit
            if (commit) begin
                aw_full <= 1'b0;
                w_full  <= 1'b0;
                bvalid  <= 1'b1;
                bresp   <= wr_ok ? RESP_OKAY : RESP_SLVERR;
                if (wr_ok) begin
                    case (aw_addr[3:2])
                        2'b00: ctrl    <= merged_ctrl;
                        2'b10: scratch <= merged_scratch;
                        default: ;
                    endcase
                end
            end else begin
                if (aw_hs) begin
                    aw_full <= 1'b1;
                    aw_addr <= s_axi_awaddr;
                end
                if (w_hs) begin
                    w_full <= 1'b1;
                    w_data <= s_axi_wdata;
                    w_strb <= s_axi_wstrb;
                end
                if (bvalid && s_axi_bready)
                    bvalid <= 1'b0;
            end

            // Read channel
            if (ar_hs) begin
                rvalid <= 1'b1;
                rdata  <= rd_aligned ? (rd_mux) : 32'd0;
                rresp  <= rd_aligned ? RESP_OKAY : RESP_SLVERR;
            end else if (rvalid && s_axi_rready) begin
                rvalid <= 1'b0;
            end
        end
    end

endmodule

module axil_regs (
    input  logic        clk,
    input  logic        rst,
    input  logic [31:0] status_in,
    input  logic [31:0] irq_set,

    input  logic [3:0]  s_axi_awaddr,
    input  logic [2:0]  s_axi_awprot,
    input  logic        s_axi_awvalid,
    output logic        s_axi_awready,

    input  logic [31:0] s_axi_wdata,
    input  logic [3:0]  s_axi_wstrb,
    input  logic        s_axi_wvalid,
    output logic        s_axi_wready,

    output logic [1:0]  s_axi_bresp,
    output logic        s_axi_bvalid,
    input  logic        s_axi_bready,

    input  logic [3:0]  s_axi_araddr,
    input  logic [2:0]  s_axi_arprot,
    input  logic        s_axi_arvalid,
    output logic        s_axi_arready,

    output logic [31:0] s_axi_rdata,
    output logic [1:0]  s_axi_rresp,
    output logic        s_axi_rvalid,
    input  logic        s_axi_rready
);

    // Register storage
    logic [31:0] ctrl_q;
    logic [31:0] scratch_q;
    logic [31:0] irq_q;

    // Write address / data slots
    logic        aw_full_q;
    logic [3:0]  aw_addr_q;
    logic        w_full_q;
    logic [31:0] w_data_q;
    logic [3:0]  w_strb_q;

    // Response state
    logic        bvalid_q;
    logic [1:0]  bresp_q;
    logic        rvalid_q;
    logic [31:0] rdata_q;
    logic [1:0]  rresp_q;

    // Ready signals
    assign s_axi_awready = !aw_full_q && !bvalid_q && !rst;
    assign s_axi_wready  = !w_full_q  && !bvalid_q && !rst;
    assign s_axi_arready = !rvalid_q && !rst;

    assign s_axi_bvalid = bvalid_q;
    assign s_axi_bresp  = bresp_q;
    assign s_axi_rvalid = rvalid_q;
    assign s_axi_rdata  = rdata_q;
    assign s_axi_rresp  = rresp_q;

    wire aw_hs = s_axi_awvalid && s_axi_awready;
    wire w_hs  = s_axi_wvalid  && s_axi_wready;
    wire ar_hs = s_axi_arvalid && s_axi_arready;
    wire b_hs  = s_axi_bvalid  && s_axi_bready;
    wire r_hs  = s_axi_rvalid  && s_axi_rready;

    wire commit = aw_full_q && w_full_q;

    // Address decode helpers
    wire        aw_aligned = (aw_addr_q[1:0] == 2'b00);
    wire [1:0]  aw_sel     = aw_addr_q[3:2];
    wire        aw_ok      = aw_aligned && (aw_sel != 2'd1);

    wire        ar_aligned = (s_axi_araddr[1:0] == 2'b00);

    wire [31:0] wmask = {{8{w_strb_q[3]}}, {8{w_strb_q[2]}},
                         {8{w_strb_q[1]}}, {8{w_strb_q[0]}}};

    wire [31:0] ctrl_next    = (ctrl_q    & ~wmask) | (w_data_q & wmask);
    wire [31:0] scratch_next = (scratch_q & ~wmask) | (w_data_q & wmask);
    wire [31:0] irq_clr      = (commit && aw_ok && aw_sel == 2'd3) ? (w_data_q & wmask) : 32'd0;

    always_ff @(posedge clk) begin
        if (rst) begin
            ctrl_q     <= '0;
            scratch_q  <= '0;
            irq_q      <= '0;
            aw_full_q  <= 1'b0;
            aw_addr_q  <= '0;
            w_full_q   <= 1'b0;
            w_data_q   <= '0;
            w_strb_q   <= '0;
            bvalid_q   <= 1'b0;
            bresp_q    <= 2'b00;
            rvalid_q   <= 1'b0;
            rdata_q    <= '0;
            rresp_q    <= 2'b00;
        end else begin
            // IRQ: set always ORed in, clear on commit of IRQ write
            irq_q <= (irq_q & ~irq_clr) | irq_set;

            // Write slots
            if (aw_hs) begin
                aw_full_q <= 1'b1;
                aw_addr_q <= s_axi_awaddr;
            end
            if (w_hs) begin
                w_full_q <= 1'b1;
                w_data_q <= s_axi_wdata;
                w_strb_q <= s_axi_wstrb;
            end

            // Write commit
            if (commit) begin
                aw_full_q <= 1'b0;
                w_full_q  <= 1'b0;
                bvalid_q  <= 1'b1;
                bresp_q   <= aw_ok ? 2'b00 : 2'b10;
                if (aw_ok) begin
                    case (aw_sel)
                        2'd0: ctrl_q    <= ctrl_next;
                        2'd2: scratch_q <= scratch_next;
                        default: ;
                    endcase
                end
            end else if (b_hs) begin
                bvalid_q <= 1'b0;
            end

            // Read
            if (ar_hs) begin
                rvalid_q <= 1'b1;
                if (ar_aligned) begin
                    case (s_axi_araddr[3:2])
                        2'd0: begin rdata_q <= ctrl_q;    rresp_q <= 2'b00; end
                        2'd1: begin rdata_q <= status_in; rresp_q <= 2'b00; end
                        2'd2: begin rdata_q <= scratch_q; rresp_q <= 2'b00; end
                        2'd3: begin rdata_q <= irq_q;     rresp_q <= 2'b00; end
                    endcase
                end else begin
                    rdata_q <= '0;
                    rresp_q <= 2'b10;
                end
            end else if (r_hs) begin
                rvalid_q <= 1'b0;
            end
        end
    end

    // Commit to registers handled above; ctrl/scratch byte writes use ctrl_next/scratch_next
    // (ensure the commit-branch assignments take effect only on commit)

endmodule

module axil_regs (
    input  logic        clk,
    input  logic        rst,
    input  logic [31:0] status_in,
    input  logic [31:0] irq_set,

    input  logic [3:0]  s_axi_awaddr,
    input  logic [2:0]  s_axi_awprot,
    input  logic        s_axi_awvalid,
    output logic        s_axi_awready,

    input  logic [31:0] s_axi_wdata,
    input  logic [3:0]  s_axi_wstrb,
    input  logic        s_axi_wvalid,
    output logic        s_axi_wready,

    output logic [1:0]  s_axi_bresp,
    output logic        s_axi_bvalid,
    input  logic        s_axi_bready,

    input  logic [3:0]  s_axi_araddr,
    input  logic [2:0]  s_axi_arprot,
    input  logic        s_axi_arvalid,
    output logic        s_axi_arready,

    output logic [31:0] s_axi_rdata,
    output logic [1:0]  s_axi_rresp,
    output logic        s_axi_rvalid,
    input  logic        s_axi_rready
);

    // Write-side slots
    logic        aw_full;
    logic [3:0]  aw_addr_q;
    logic        w_full;
    logic [31:0] w_data_q;
    logic [3:0]  w_strb_q;

    // Register state
    logic [31:0] ctrl_q;
    logic [31:0] scratch_q;
    logic [31:0] irq_q;

    // Handshakes
    logic aw_hs, w_hs, ar_hs, commit;
    assign s_axi_awready = !rst && !aw_full && !s_axi_bvalid;
    assign s_axi_wready  = !rst && !w_full  && !s_axi_bvalid;
    assign s_axi_arready = !rst && !s_axi_rvalid;

    assign aw_hs  = s_axi_awvalid && s_axi_awready;
    assign w_hs   = s_axi_wvalid  && s_axi_wready;
    assign ar_hs  = s_axi_arvalid && s_axi_arready;
    assign commit = aw_full && w_full;

    // Decode of write address
    logic       wr_aligned;
    logic [1:0] wr_sel;
    logic       wr_ok;
    assign wr_aligned = (aw_addr_q[1:0] == 2'b00);
    assign wr_sel     = aw_addr_q[3:2];
    assign wr_ok      = wr_aligned && (wr_sel != 2'd1);

    // Decode of read address
    logic       rd_aligned;
    logic       rd_ok;
    logic [31:0] rd_data_next;
    assign rd_aligned = (s_axi_araddr[1:0] == 2'b00);
    assign rd_ok      = rd_aligned;

    always_comb begin
        rd_data_next = 32'd0;
        if (rd_aligned) begin
            case (s_axi_araddr[3:2])
                2'd0:    rd_data_next = ctrl_q;
                2'd1:    rd_data_next = status_in;
                2'd2:    rd_data_next = scratch_q;
                default: rd_data_next = irq_q;
            endcase
        end
    end

    // Byte-merge function
    function automatic logic [31:0] merge_bytes(
        input logic [31:0] old_v,
        input logic [31:0] new_v,
        input logic [3:0]  strb
    );
        logic [31:0] r;
        for (int i = 0; i < 4; i++) begin
            r[8*i +: 8] = strb[i] ? new_v[8*i +: 8] : old_v[8*i +: 8];
        end
        return r;
    endfunction

    // IRQ clear mask (bits where data and strobe are both one)
    logic [31:0] irq_clr_mask;
    always_comb begin
        for (int i = 0; i < 4; i++) begin
            irq_clr_mask[8*i +: 8] = w_data_q[8*i +: 8] & {8{w_strb_q[i]}};
        end
    end

    logic irq_wr;
    assign irq_wr = commit && wr_aligned && (wr_sel == 2'd3);

    always_ff @(posedge clk) begin
        if (rst) begin
            aw_full     <= 1'b0;
            aw_addr_q   <= 4'd0;
            w_full      <= 1'b0;
            w_data_q    <= 32'd0;
            w_strb_q    <= 4'd0;
            s_axi_bvalid <= 1'b0;
            s_axi_bresp  <= 2'b00;
            s_axi_rvalid <= 1'b0;
            s_axi_rdata  <= 32'd0;
            s_axi_rresp  <= 2'b00;
            ctrl_q      <= 32'd0;
            scratch_q   <= 32'd0;
            irq_q       <= 32'd0;
        end else begin
            // Write address slot
            if (aw_hs) begin
                aw_full   <= 1'b1;
                aw_addr_q <= s_axi_awaddr;
            end else if (commit) begin
                aw_full   <= 1'b0;
            end

            // Write data slot
            if (w_hs) begin
                w_full   <= 1'b1;
                w_data_q <= s_axi_wdata;
                w_strb_q <= s_axi_wstrb;
            end else if (commit) begin
                w_full   <= 1'b0;
            end

            // Write commit and B channel
            if (commit) begin
                s_axi_bvalid <= 1'b1;
                s_axi_bresp  <= wr_ok ? 2'b00 : 2'b10;
                if (wr_ok) begin
                    case (wr_sel)
                        2'd0: ctrl_q    <= merge_bytes(ctrl_q, w_data_q, w_strb_q);
                        2'd2: scratch_q <= merge_bytes(scratch_q, w_data_q, w_strb_q);
                        default: ;
                    endcase
                end
            end else if (s_axi_bvalid && s_axi_bready) begin
                s_axi_bvalid <= 1'b0;
            end

            // IRQ register: set always, clear on IRQ write commit
            irq_q <= (irq_q & ~(irq_wr ? irq_clr_mask : 32'd0)) | irq_set;

            // Read channel
            if (ar_hs) begin
                s_axi_rvalid <= 1'b1;
                s_axi_rdata  <= rd_data_next;
                s_axi_rresp  <= rd_ok ? 2'b00 : 2'b10;
            end else if (s_axi_rvalid && s_axi_rready) begin
                s_axi_rvalid <= 1'b0;
            end
        end
    end

endmodule

module mul_pipe3 #(
    parameter integer WIDTH = 16
) (
    input  logic                      clk,
    input  logic                      rst,
    input  logic                      in_valid,
    input  logic signed [WIDTH-1:0]   a,
    input  logic signed [WIDTH-1:0]   b,
    output logic                      out_valid,
    output logic signed [2*WIDTH-1:0] product
);

    // Stage 1: operand capture (edge k)
    logic signed [WIDTH-1:0]   a1, b1;
    logic                      v1;
    // Stage 2: full signed product (edge k+1)
    logic signed [2*WIDTH-1:0] p2;
    logic                      v2;
    // Stage 3: delay (edge k+2)
    logic signed [2*WIDTH-1:0] p3;
    logic                      v3;

    always_ff @(posedge clk) begin
        if (rst) begin
            v1        <= 1'b0;
            v2        <= 1'b0;
            v3        <= 1'b0;
            out_valid <= 1'b0;
            product   <= '0;
        end else begin
            v1        <= in_valid;
            v2        <= v1;
            v3        <= v2;
            out_valid <= v3;
            product   <= v3 ? p3 : '0;
        end
    end

    always_ff @(posedge clk) begin
        a1 <= a;
        b1 <= b;
        p2 <= $signed(a1) * $signed(b1);
        p3 <= p2;
    end

endmodule

