module mul_pipe3 #(
    parameter integer WIDTH = 16
) (
    input  logic                      clk,
    input  logic                      rst,
    input  logic                      in_valid,
    input  logic signed [WIDTH-1:0]   a,
    input  logic signed [WIDTH-1:0]   b,
    output logic                      out_valid,
    output logic signed [2*WIDTH-1:0] product
);

    // Stage 1: operand capture (acceptance edge k)
    logic                      v1;
    logic signed [WIDTH-1:0]   a1, b1;
    // Stage 2: operand forwarding (edge k+1)
    logic                      v2;
    logic signed [WIDTH-1:0]   a2, b2;
    // Stage 3: product register (edge k+2)
    logic                      v3;
    logic signed [2*WIDTH-1:0] p3;

    // Sign-extended operands for exact 2*WIDTH-bit signed product
    logic signed [2*WIDTH-1:0] ea, eb;
    assign ea = {{WIDTH{a2[WIDTH-1]}}, a2};
    assign eb = {{WIDTH{b2[WIDTH-1]}}, b2};

    always_ff @(posedge clk) begin
        if (rst) begin
            v1 <= 1'b0;
            v2 <= 1'b0;
            v3 <= 1'b0;
            out_valid <= 1'b0;
            product   <= '0;
            a1 <= '0;
            b1 <= '0;
            a2 <= '0;
            b2 <= '0;
            p3 <= '0;
        end else begin
            v1 <= in_valid;
            a1 <= a;
            b1 <= b;

            v2 <= v1;
            a2 <= a1;
            b2 <= b1;

            v3 <= v2;
            p3 <= ea * eb;

            out_valid <= v3;
            product   <= v3 ? p3 : '0;
        end
    end

endmodule

