module crc32_stream (
    input  logic        clk,
    input  logic        rst,
    input  logic        start,
    input  logic        in_valid,
    input  logic [7:0]  data,
    output logic        out_valid,
    output logic [31:0] crc
);

    localparam logic [31:0] POLY    = 32'hEDB8_8320;
    localparam logic [31:0] ALL_ONE = 32'hFFFF_FFFF;

    logic [31:0] rem;

    // Process one byte, bit 0 first, starting from remainder r.
    function automatic logic [31:0] crc_byte(input logic [31:0] r_in, input logic [7:0] d);
        logic [31:0] r;
        logic        mix;
        begin
            r = r_in;
            for (int i = 0; i < 8; i++) begin
                mix = r[0] ^ d[i];
                r   = r >> 1;
                if (mix)
                    r = r ^ POLY;
            end
            crc_byte = r;
        end
    endfunction

    logic [31:0] init_rem;
    logic [31:0] next_rem;

    always_comb begin
        init_rem = start ? ALL_ONE : rem;
        if (in_valid)
            next_rem = crc_byte(init_rem, data);
        else
            next_rem = init_rem;
    end

    always_ff @(posedge clk) begin
        if (rst) begin
            rem       <= ALL_ONE;
            crc       <= 32'h0000_0000;
            out_valid <= 1'b0;
        end else begin
            rem       <= next_rem;
            out_valid <= in_valid;
            if (in_valid || start)
                crc <= next_rem ^ ALL_ONE;
            // otherwise gap with no start: crc holds its value
        end
    end

endmodule

module crc32_stream (
    input  logic        clk,
    input  logic        rst,
    input  logic        start,
    input  logic        in_valid,
    input  logic [7:0]  data,
    output logic        out_valid,
    output logic [31:0] crc
);

    logic [31:0] rem;

    function automatic logic [31:0] crc_byte(input logic [31:0] r_in,
                                             input logic [7:0]  d);
        logic [31:0] r;
        logic        mix;
        begin
            r = r_in;
            for (int i = 0; i < 8; i++) begin
                mix = r[0] ^ d[i];
                r   = r >> 1;
                if (mix) r = r ^ 32'hEDB8_8320;
            end
            crc_byte = r;
        end
    endfunction

    logic [31:0] init_rem;
    logic [31:0] next_rem;

    always_comb begin
        init_rem = start ? 32'hFFFF_FFFF : rem;
        next_rem = in_valid ? crc_byte(init_rem, data) : init_rem;
    end

    always_ff @(posedge clk) begin
        if (rst) begin
            rem       <= 32'hFFFF_FFFF;
            crc       <= 32'h0000_0000;
            out_valid <= 1'b0;
        end else begin
            rem       <= next_rem;
            crc       <= next_rem ^ 32'hFFFF_FFFF;
            out_valid <= in_valid;
        end
    end

endmodule

module crc32_stream (
    input  logic        clk,
    input  logic        rst,
    input  logic        start,
    input  logic        in_valid,
    input  logic [7:0]  data,
    output logic        out_valid,
    output logic [31:0] crc
);

    localparam logic [31:0] POLY = 32'hEDB8_8320;
    localparam logic [31:0] ALL1 = 32'hFFFF_FFFF;

    logic [31:0] rem;
    logic [31:0] base;
    logic [31:0] rem_next;

    function automatic logic [31:0] crc8_step(input logic [31:0] r, input logic [7:0] d);
        logic [31:0] c;
        logic        mix;
        begin
            c = r;
            for (int i = 0; i < 8; i++) begin
                mix = c[0] ^ d[i];
                c   = c >> 1;
                if (mix) c = c ^ POLY;
            end
            crc8_step = c;
        end
    endfunction

    always_comb begin
        base = start ? ALL1 : rem;
    end

    always_comb begin
        rem_next = in_valid ? crc8_step(base, data) : base;
    end

    always_ff @(posedge clk) begin
        if (rst) begin
            rem       <= ALL1;
            out_valid <= 1'b0;
        end else begin
            rem       <= rem_next;
            out_valid <= in_valid;
        end
    end

    always_comb begin
        crc = rem ^ ALL1;
    end

endmodule

module crc32_stream (
