    output logic [31:0] crc
);

    localparam logic [31:0] POLY = 32'hEDB8_8320;
    localparam logic [31:0] INIT = 32'hFFFF_FFFF;

    logic [31:0] rem;

    // Process one byte, bit 0 first, into the given remainder.
    function automatic logic [31:0] crc_byte(input logic [31:0] r_in,
                                             input logic [7:0]  d);
        logic [31:0] r;
        logic        mix;
        begin
            r = r_in;
            for (int i = 0; i < 8; i++) begin
                mix = r[0] ^ d[i];
                r   = r >> 1;
                if (mix) r = r ^ POLY;
            end
            crc_byte = r;
        end
    endfunction

    logic [31:0] base;
    logic [31:0] nxt;

    always_comb begin
        base = start ? INIT : rem;
        nxt  = in_valid ? crc_byte(base, data) : base;
    end

    always_ff @(posedge clk) begin
        if (rst) begin
            rem       <= INIT;
            out_valid <= 1'b0;
        end else begin
            rem       <= nxt;
            out_valid <= in_valid;
        end
    end

    assign crc = rem ^ INIT;

endmodule

